module geometry;

struct Point { x: F64, y: F64 }

fn distance_sq(p: in Point) -> F64 {
    return p.x * p.x + p.y * p.y;
}

spec "distance_sq of origin is zero" {
    given let origin = Point { x: 0.0, y: 0.0 };
    when let d = distance_sq(origin);
    then d == 0.0;
}

module geometry;

struct Point { x: float, y: float }

function distance_sq(p: in Point) -> float {
    return p.x * p.x + p.y * p.y;
}

test "distance_sq of origin is zero" {
    given let origin = Point { x: 0.0, y: 0.0 };
    when let d = distance_sq(origin);
    then d == 0.0;
}
